/// Max audio length per single request in seconds\n  maxFileDurationSec   Int?             @map(\"max_file_duration_sec\")\n  /// Max parallel background jobs\n  concurrentJobs       Int              @default(1) @map(\"concurrent_jobs\") @db.SmallInt\n  /// Access to isPremium voice models\n  hasPremiumVoices     Boolean          @default(false) @map(\"has_premium_voices\")\n  /// Programmatic API access (for developer/enterprise plans)\n  hasApiAccess         Boolean          @default(false) @map(\"has_api_access\")\n  /// Additional feature flags as JSON\n  features             Json?            @default(\"{}\")\n  stripeMonthlyPriceId String?          @map(\"stripe_price_id_monthly\") @db.VarChar(255)\n  stripeYearlyPriceId  String?          @map(\"stripe_price_id_yearly\") @db.VarChar(255)\n  isActive             Boolean          @default(true) @map(\"is_active\")\n  createdAt            DateTime         @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt            DateTime         @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  subscriptions        Subscription[]\n  usageAnalytics       UsageAnalytics[]\n\n  @@index([slug], map: \"idx_plans_slug\")\n  @@index([isActive], map: \"idx_plans_is_active\")\n  @@map(\"plans\")\n}\n\n/// User subscription to a plan.\n/// NOTE: Enforce one-active-per-user via raw SQL partial unique index:\n/// CREATE UNIQUE INDEX uq_subscriptions_user_active\n/// ON subscriptions (user_id)\n/// WHERE status IN ('active', 'trialing');\nmodel Subscription {\n  id                   String             @id @default(uuid()) @db.Uuid\n  userId               String             @map(\"user_id\") @db.Uuid\n  planId               String             @map(\"plan_id\") @db.Uuid\n  status               SubscriptionStatus @default(active)\n  /// monthly | yearly\n  billingCycle         String             @default(\"monthly\") @map(\"billing_cycle\") @db.VarChar(10)\n  currentPeriodStart   DateTime           @map(\"current_period_start\") @db.Timestamptz(6)\n  currentPeriodEnd     DateTime           @map(\"current_period_end\") @db.Timestamptz(6)\n  /// NULL = no trial period\n  trialEndsAt          DateTime?          @map(\"trial_ends_at\") @db.Timestamptz(6)\n  cancelledAt          DateTime?          @map(\"cancelled_at\") @db.Timestamptz(6)\n  stripeSubscriptionId String?            @map(\"stripe_subscription_id\") @db.VarChar(255)\n  stripeCustomerId     String?            @map(\"stripe_customer_id\") @db.VarChar(255)\n  metadata             Json?              @default(\"{}\")\n  createdAt            DateTime           @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt            DateTime           @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  invoices             Invoice[]\n  plan                 Plan               @relation(fields: [planId], references: [id])\n  user                 User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId], map: \"idx_subscriptions_user_id\")\n  @@index([status], map: \"idx_subscriptions_status\")\n  @@index([stripeSubscriptionId], map: \"idx_subscriptions_stripe_id\")\n  @@map(\"subscriptions\")\n}\n\n/// One invoice per billing period per subscription.\nmodel Invoice {\n  id              String        @id @default(uuid()) @db.Uuid\n  subscriptionId  String        @map(\"subscription_id\") @db.Uuid\n  /// Denormalized for fast user invoice listing\n  userId          String        @map(\"user_id\") @db.Uuid\n  status          InvoiceStatus @default(draft)\n  /// Total amount in cents\n  amountCents     Int           @map(\"amount_cents\")\n  /// ISO 4217: USD, EUR, etc.\n  currency        String        @default(\"USD\") @db.Char(3)\n  periodStart     DateTime      @map(\"period_start\") @db.Timestamptz(6)\n  periodEnd       DateTime      @map(\"period_end\") @db.Timestamptz(6)\n  paidAt          DateTime?     @map(\"paid_at\") @db.Timestamptz(6)\n  stripeInvoiceId String?       @map(\"stripe_invoice_id\") @db.VarChar(255)\n  pdfUrl          String?       @map(\"pdf_url\")\n  createdAt       DateTime      @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  items           InvoiceItem[]\n  subscription    Subscription  @relation(fields: [subscriptionId], references: [id])\n  user            User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId], map: \"idx_invoices_user_id\")\n  @@index([subscriptionId], map: \"idx_invoices_subscription_id\")\n  @@index([status], map: \"idx_invoices_status\")\n  @@map(\"invoices\")\n}\n\n/// Line items within an invoice.\nmodel InvoiceItem {\n  id             String   @id @default(uuid()) @db.Uuid\n  invoiceId      String   @map(\"invoice_id\") @db.Uuid\n  /// \"Pro Plan — Monthly\", \"Character Overage (50k chars)\"\n  description    String\n  quantity       Int      @default(1)\n  /// Price per unit in cents\n  unitPriceCents Int      @map(\"unit_price_cents\")\n  /// quantity × unitPriceCents\n  totalCents     Int      @map(\"total_cents\")\n  /// plan | overage | addon | credit | tax\n  type           String   @db.VarChar(50)\n  createdAt      DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  invoice        Invoice  @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId], map: \"idx_invoice_items_invoice_id\")\n  @@map(\"invoice_items\")\n}\n\n/// Aggregated daily usage metrics per user.\n/// Written by a background summarizer that rolls up tts_requests data.\n/// Powers user dashboard and admin analytics.\nmodel UsageAnalytics {\n  id                 BigInt   @id @default(autoincrement())\n  userId             String   @map(\"user_id\") @db.Uuid\n  date               DateTime @db.Date\n  /// Plan active on this date (for historical plan tracking)\n  planId             String?  @map(\"plan_id\") @db.Uuid\n  requestCount       Int      @default(0) @map(\"request_count\")\n  completedCount     Int      @default(0) @map(\"completed_count\")\n  failedCount        Int      @default(0) @map(\"failed_count\")\n  cachedCount        Int      @default(0) @map(\"cached_count\")\n  totalChars         BigInt   @default(0) @map(\"total_chars\")\n  totalDurationSec   Decimal  @default(0) @map(\"total_duration_sec\") @db.Decimal(12, 3)\n  totalFileSizeBytes BigInt   @default(0) @map(\"total_file_size_bytes\")\n  apiCalls           Int      @default(0) @map(\"api_calls\")\n  rateLimitHits      Int      @default(0) @map(\"rate_limit_hits\")\n  createdAt          DateTime @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  updatedAt          DateTime @updatedAt @map(\"updated_at\") @db.Timestamptz(6)\n  plan               Plan?    @relation(fields: [planId], references: [id])\n  user               User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date], map: \"uq_usage_analytics_user_date\")\n  @@index([userId, date], map: \"idx_usage_analytics_user_date\")\n  @@index([date], map: \"idx_usage_analytics_date\")\n  @@map(\"usage_analytics\")\n}\n\n/// TTS result deduplication cache.\n/// cache_key = SHA-256(inputText + elVoiceId + elModelId + languageCode + outputFormat)\n/// Cache HIT = serve existing audio file, zero EL API cost.\nmodel RequestCache {\n  id           String     @id @default(uuid()) @db.Uuid\n  /// SHA-256 of the canonical request parameters\n  cacheKey     String     @unique @map(\"cache_key\") @db.VarChar(64)\n  /// The cached audio output\n  audioFileId  String     @map(\"audio_file_id\") @db.Uuid\n  voiceModelId String     @map(\"voice_model_id\") @db.Uuid\n  /// mp3 | wav | ogg | flac\n  outputFormat String     @map(\"output_format\") @db.VarChar(10)\n  charCount    Int        @map(\"char_count\")\n  /// Total number of times this cache entry was served\n  hitCount     Int        @default(0) @map(\"hit_count\")\n  lastHitAt    DateTime?  @map(\"last_hit_at\") @db.Timestamptz(6)\n  /// NULL = never expires; set for volatile content\n  isPinned     Boolean    @default(false) @map(\"is_pinned\")\n  expiresAt    DateTime?  @map(\"expires_at\") @db.Timestamptz(6)\n  createdAt    DateTime   @default(now()) @map(\"created_at\") @db.Timestamptz(6)\n  audioFile    AudioFile  @relation(fields: [audioFileId], references: [id])\n  voiceModel   VoiceModel @relation(fields: [voiceModelId], references: [id])\n\n  @@index([cacheKey], map: \"idx_request_cache_cache_key\")\n  @@index([expiresAt], map: \"idx_request_cache_expires_at\")\n  @@index([lastHitAt], map: \"idx_request_cache_last_hit_at\")\n  @@map(\"request_cache\")\n}\n\nenum RequestStatus {\n  pending\n  queued\n  processing\n  completed\n  failed\n  cancelled\n\n  @@map(\"request_status\")\n}\n\nenum JobStatus {\n  waiting\n  active\n  completed\n  failed\n  delayed\n  cancelled\n\n  @@map(\"job_status\")\n}\n\nenum SubscriptionStatus {\n  active\n  trialing\n  past_due\n  cancelled\n  expired\n\n  @@map(\"subscription_status\")\n}\n\nenum InvoiceStatus {\n  draft\n  open\n  paid\n  void\n  uncollectible\n\n  @@map(\"invoice_status\")\n}\n",
